19	/**
20	 * Display a formatted list of hooks with their status
21	 */
22	async function panelAction(
23	  context: CommandContext,
24	): Promise<void | MessageActionReturn> {
25	  const { config } = context.services;
26	  if (!config) {
27	    return {
28	      type: 'message',
29	      messageType: 'error',
30	      content: 'Config not loaded.',
31	    };
32	  }
33	
34	  const hookSystem = config.getHookSystem();
35	  const allHooks = hookSystem?.getAllHooks() || [];
36	
37	  const hooksListItem: HistoryItemHooksList = {
38	    type: MessageType.HOOKS_LIST,
39	    hooks: allHooks,
40	  };
41	
42	  context.ui.addItem(hooksListItem);
43	}
44	
45	/**
46	 * Enable a hook by name
47	 */
48	async function enableAction(
49	  context: CommandContext,
50	  args: string,
51	): Promise<void | MessageActionReturn> {
52	  const { config } = context.services;
53	  if (!config) {
54	    return {
55	      type: 'message',
56	      messageType: 'error',
57	      content: 'Config not loaded.',
58	    };
59	  }
60	
61	  const hookSystem = config.getHookSystem();
62	  if (!hookSystem) {
63	    return {
64	      type: 'message',
65	      messageType: 'error',
66	      content: 'Hook system is not enabled.',
67	    };
68	  }
69	
70	  const hookName = args.trim();
71	  if (!hookName) {
72	    return {
73	      type: 'message',
74	      messageType: 'error',
75	      content: 'Usage: /hooks enable <hook-name>',
76	    };
77	  }
78	
79	  const settings = context.services.settings;
80	  const result = enableHook(settings, hookName);
81	
82	  if (result.status === 'success') {
83	    hookSystem.setHookEnabled(hookName, true);
84	  }
85	
86	  const feedback = renderHookActionFeedback(
87	    result,
88	    (label, path) => `${label} (${path})`,
89	  );
90	
91	  return {
92	    type: 'message',
93	    messageType: result.status === 'error' ? 'error' : 'info',
94	    content: feedback,
95	  };
96	}
97	
98	/**
99	 * Disable a hook by name
100	 */
101	async function disableAction(
102	  context: CommandContext,
103	  args: string,
104	): Promise<void | MessageActionReturn> {
105	  const { config } = context.services;
106	  if (!config) {
107	    return {
108	      type: 'message',
109	      messageType: 'error',
110	      content: 'Config not loaded.',
111	    };
112	  }
113	
114	  const hookSystem = config.getHookSystem();
115	  if (!hookSystem) {
116	    return {
117	      type: 'message',
118	      messageType: 'error',
119	      content: 'Hook system is not enabled.',
120	    };
121	  }
122	
123	  const hookName = args.trim();
124	  if (!hookName) {
125	    return {
126	      type: 'message',
127	      messageType: 'error',
128	      content: 'Usage: /hooks disable <hook-name>',
129	    };
130	  }
131	
132	  const settings = context.services.settings;
133	  const scope = settings.workspace ? SettingScope.Workspace : SettingScope.User;
134	
135	  const result = disableHook(settings, hookName, scope);
136	
137	  if (result.status === 'success') {
138	    hookSystem.setHookEnabled(hookName, false);
139	  }
140	
141	  const feedback = renderHookActionFeedback(
142	    result,
143	    (label, path) => `${label} (${path})`,
144	  );
145	
146	  return {
147	    type: 'message',
148	    messageType: result.status === 'error' ? 'error' : 'info',
149	    content: feedback,
150	  };
151	}
