153	/**
154	 * Completion function for enabled hook names (to be disabled)
155	 */
156	function completeEnabledHookNames(
157	  context: CommandContext,
158	  partialArg: string,
159	): string[] {
160	  const { config } = context.services;
161	  if (!config) return [];
162	
163	  const hookSystem = config.getHookSystem();
164	  if (!hookSystem) return [];
165	
166	  const allHooks = hookSystem.getAllHooks();
167	  return allHooks
168	    .filter((hook) => hook.enabled)
169	    .map((hook) => getHookDisplayName(hook))
170	    .filter((name) => name.startsWith(partialArg));
171	}
172	
173	/**
174	 * Completion function for disabled hook names (to be enabled)
175	 */
176	function completeDisabledHookNames(
177	  context: CommandContext,
178	  partialArg: string,
179	): string[] {
180	  const { config } = context.services;
181	  if (!config) return [];
182	
183	  const hookSystem = config.getHookSystem();
184	  if (!hookSystem) return [];
185	
186	  const allHooks = hookSystem.getAllHooks();
187	  return allHooks
188	    .filter((hook) => !hook.enabled)
189	    .map((hook) => getHookDisplayName(hook))
190	    .filter((name) => name.startsWith(partialArg));
191	}
192	
193	/**
194	 * Get a display name for a hook
195	 */
196	function getHookDisplayName(hook: HookRegistryEntry): string {
197	  return hook.config.name || hook.config.command || 'unknown-hook';
198	}
