/**
 * Display a formatted list of hooks with their status
 */
async function panelAction(
  context: CommandContext,
): Promise<MessageActionReturn | OpenCustomDialogActionReturn> {
  const { config } = context.services;
  if (!config) {
    return {
      type: 'message',
      messageType: 'error',
      content: 'Config not loaded.',
    };
  }

  const hookSystem = config.getHookSystem();
  const allHooks = hookSystem?.getAllHooks() || [];

  const hooks: HookEntry[] = allHooks.map((hook) => ({
    config: {
      name: hook.config.name,
      command: hook.config.command,
      type: hook.config.type,
      description: hook.config.description,
      timeout: hook.config.timeout,
    },
    source: hook.source,
    eventName: hook.eventName,
    matcher: hook.matcher,
    sequential: hook.sequential,
    enabled: hook.enabled,
  }));

  return {
    type: 'custom_dialog',
    component: (
      <HooksDialog hooks={hooks} onClose={() => context.ui.removeComponent()} />
    ),
  };
}

/**
 * Enable a hook by name
 */
async function enableAction(
  context: CommandContext,
  args: string,
): Promise<void | MessageActionReturn> {
  const { config } = context.services;
  if (!config) {
    return {
      type: 'message',
      messageType: 'error',
      content: 'Config not loaded.',
    };
  }

  const hookSystem = config.getHookSystem();
  if (!hookSystem) {
    return {
      type: 'message',
      messageType: 'error',
      content: 'Hook system is not enabled.',
    };
  }

  const hookName = args.trim();
  if (!hookName) {
    return {
      type: 'message',
      messageType: 'error',
      content: 'Usage: /hooks enable <hook-name>',
    };
  }

  const settings = context.services.settings;
  const result = enableHook(settings, hookName);

  if (result.status === 'success') {
    hookSystem.setHookEnabled(hookName, true);
  }

  const feedback = renderHookActionFeedback(
    result,
    (label, path) => `${label} (${path})`,
  );

  return {
    type: 'message',
    messageType: result.status === 'error' ? 'error' : 'info',
    content: feedback,
  };
}

