}

/**
 * An interactive dialog for browsing configured hooks. Unlike the message-feed
 * based listing, this component owns its own keyboard focus: it can be scrolled
 * with the arrow keys and dismissed with Escape.
 */
export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks,
}) => {
  const [scrollOffset, setScrollOffset] = useState(0);

  const totalHooks = hooks.length;
  const isScrollable =
    maxVisibleHooks !== undefined && totalHooks > maxVisibleHooks;
  const maxScrollOffset = isScrollable
    ? Math.max(0, totalHooks - maxVisibleHooks)
    : 0;

  useKeypress(
    useCallback(
      (key) => {
        if (key.name === 'escape') {
          onClose();
          return;
        }

        if (!isScrollable) {
          return;
        }

        if (key.name === 'up') {
          setScrollOffset((offset) => Math.max(0, offset - 1));
        } else if (key.name === 'down') {
          setScrollOffset((offset) => Math.min(maxScrollOffset, offset + 1));
        }
      },
      [onClose, isScrollable, maxScrollOffset],
    ),
    { isActive: true },
  );

  // The hooks currently visible within the scroll window.
  const visibleHooks = useMemo(() => {
    if (maxVisibleHooks === undefined) {
      return hooks;
    }
    return hooks.slice(scrollOffset, scrollOffset + maxVisibleHooks);
  }, [hooks, scrollOffset, maxVisibleHooks]);

  // Group the visible hooks by their event name for organized display.
  const hooksByEvent = useMemo(() => {
    return visibleHooks.reduce(
      (acc, hook) => {
        if (!acc[hook.eventName]) {
          acc[hook.eventName] = [];
        }
        acc[hook.eventName].push(hook);
        return acc;
      },
      {} as Record<string, HookEntry[]>,
    );
  }, [visibleHooks]);

  const showScrollUp = isScrollable && scrollOffset > 0;
  const showScrollDown = isScrollable && scrollOffset < maxScrollOffset;

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.border.default}
      paddingX={1}
    >
      <Box flexDirection="column">
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text>
          Learn more:{' '}
          <Text color={theme.text.link}>https://geminicli.com/docs/hooks</Text>
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text bold>Configured Hooks:</Text>
      </Box>

      {totalHooks === 0 ? (
        <Box marginTop={1}>
          <Text>No hooks configured.</Text>
