    : 0;

  useKeypress(
    useCallback(
      (key) => {
        if (key.name === 'escape') {
          onClose();
          return;
        }

        if (!isScrollable) {
          return;
        }

        if (key.name === 'up') {
          setScrollOffset((offset) => Math.max(0, offset - 1));
        } else if (key.name === 'down') {
          setScrollOffset((offset) => Math.min(maxScrollOffset, offset + 1));
        }
      },
      [onClose, isScrollable, maxScrollOffset],
    ),
    { isActive: true },
  );

