                            {hook.config.timeout &&
                              ` | Timeout: ${hook.config.timeout}s`}
                          </Text>
                        </Box>
                      </Box>
                    );
                  })}
                </Box>
              </Box>
            ))}
          </Box>
          <Box>
            <Text color={theme.text.secondary}>
              {showScrollDown ? '▼' : ' '}
            </Text>
          </Box>
